// Dev-mode service worker placeholder.
// Production sw.js is generated by vite-plugin-pwa and imports push-handlers.js.
// Dev still needs a real SW for PushManager.subscribe(), so load the same handlers.
try {
  importScripts('/push-handlers.js');
} catch (err) {
  // Keep dev boot resilient if the handler file is temporarily unavailable.
  console.warn('[tower-sw] push handlers unavailable', err);
}
